/*
 * A308787  Primes p such that A001175(p) = (p-1)/2.
 * https://oeis.org/A308787
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   the n‑th prime p such that the Pisano period of the Fibonacci *
 *            sequence modulo p equals (p-1)/2. The sequence is generated by *
 *            scanning primes and testing the period using fast doubling
 * Range:     u8 n <= 5, u16 n <= 46, u32 n <= 46, u64 n <= 46, u128 n <= 46,
 *            big any n
 * Helpers:   build_spf
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/build_spf.h"

/* ----------  Fibonacci fast doubling – O(log n)  ---------- */
static void fib_pair(idx_t n, seq_t mod, seq_t *fn, seq_t *fn1)
{
    if (n == 0) {
        *fn  = 0;
        *fn1 = 1;
        return;
    }
    seq_t a, b, c, d;
    fib_pair(n >> 1, mod, &a, &b);               /* (F_k , F_{k+1}) */
    /* F_{2k} = F_k * (2*F_{k+1} - F_k) */
    seq_t two_b = (b * 2) % mod;
    seq_t val   = (two_b + mod - a) % mod;       /* (2*F_k - F_{k-1})  */
    c = (a * val) % mod;
    /* F_{2k+1} = F_k^2 + F_{k+1}^2 */
    d = (a * a % mod + b * b % mod) % mod;
    if (n & 1) {
        *fn  = d;
        *fn1 = (c + d) % mod;
    } else {
        *fn  = c;
        *fn1 = d;
    }
}

/* ----------  State for sequence generation  ---------- */
struct seq_state {
    uint64_t      limit;      /* current sieve limit            */
    uint64_t     *spf;        /* smallest prime factor table    */
    uint64_t     *primes;     /* list of primes up to limit     */
    size_t        prime_cnt;  /* number of primes in the list   */
    size_t        last_prime; /* index of next prime to examine*/
    size_t        good_cnt;   /* number of qualified primes    */
    size_t        good_cap;   /* capacity of `good`             */
    uint64_t     *good;       /* array of qualified primes     */
} st = {0, NULL, NULL, 0, 0, 0, 0, NULL};

/* ----------  Ensure enough qualified primes are in st.good  ---------- */
static void ensure_good(idx_t need)
{
    /* Grow sieve and prime list until we have processed enough primes. */
    while (st.good_cnt < need) {
        /* Rebuild sieve / prime list if we exhausted the current list. */
        if (st.last_prime >= st.prime_cnt) {
            if (st.limit == 0) st.limit = 1000;
            else               st.limit <<= 1;          /* double */

            free(st.spf);
            build_spf(st.limit, &st.spf);

            /* Count primes in the new range. */
            size_t cnt = 0;
            for (uint64_t i = 2; i <= st.limit; ++i)
                if (st.spf[i] == i) ++cnt;

            /* Reallocate and refill prime list. */
            uint64_t *new_primes = (uint64_t*)malloc(cnt * sizeof(uint64_t));
            size_t   j = 0;
            for (uint64_t i = 2; i <= st.limit; ++i)
                if (st.spf[i] == i) new_primes[j++] = i;

            free(st.primes);
            st.primes   = new_primes;
            st.prime_cnt = cnt;
            /* No change to st.last_prime – it points into the new list. */
        }

        /* Examine the next prime. */
        uint64_t p = st.primes[st.last_prime++];
        if (p < 5) continue;         /* skip 2,3,5 */
        if (p % 5 != 1 && p % 5 != 4) continue; /* (5/p)=1 required */

        uint64_t t = p - 1;          /* period divides t          */
        uint64_t period = t;

        /* Factorise t using the SPF table. */
        uint64_t tmp = t;
        while (tmp > 1) {
            uint64_t f = st.spf[tmp];
            if (f == 0) f = tmp;           /* safety for primes > current limit */

            /* Remove all occurrences of f from tmp. */
            while (tmp % f == 0) tmp /= f;

            /* Try to reduce period by the prime factor f. */
            while (period % f == 0) {
                uint64_t cand = period / f;
                seq_t fn, fn1;
                fib_pair((idx_t)cand, (seq_t)p, &fn, &fn1);
                if (fn == 0 && fn1 == 1)
                    period = cand;          /* reduction succeeded */
                else
                    break;                  /* cannot reduce further by f */
            }
        }

        /* Accept p if period halves t. */
        if (period == t / 2) {
            if (st.good_cnt >= st.good_cap) {
                st.good_cap = st.good_cap ? st.good_cap * 2 : 32;
                uint64_t *new_good = (uint64_t*)realloc(st.good,
                                                  st.good_cap * sizeof(uint64_t));
                st.good = new_good;
            }
            st.good[st.good_cnt++] = p;
        }
    }
}

/* ----------  Sequence entry function  ---------- */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* value undefined for n=0, guard clause */
    ensure_good(n);
    return (seq_t)st.good[n - 1];
}
